(function(root){
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
function lines(text,width=25){const words=text.trim().split(/\s+/);const out=[];let line='';for(const w of words){if((line+' '+w).trim().length>width&&line){out.push(line);line='';}line+=(line?' ':'')+w;}if(line)out.push(line);return out;}
function svg({title,type='CERTIFICATE',style='ribbon',id=''}){if(!title?.trim()||title.length>180)throw Error('Enter a title between 1 and 180 characters.');const seal=style==='seal',simple=style==='shield',micro=style==='micro';const navy='#073568',gold='#dbb24b',cyan=seal?'#328493':'#00a9d8';const textLines=lines(title.toUpperCase(),27);const size=Math.min(32,150/textLines.length,680/Math.max(...textLines.map(s=>s.length)) *1.65);const text=textLines.map((s,i)=>`<text x="400" y="${440+i*(size+7)}" font-size="${size}" font-weight="700">${escape(s)}</text>`).join('');const outline=seal?`<circle cx="400" cy="390" r="350" fill="${gold}"/><circle cx="400" cy="390" r="329" fill="#fffaf0"/><circle cx="400" cy="390" r="285" fill="${navy}"/>`:`<path d="M400 35 L725 155 L705 495 Q690 650 400 765 Q110 650 95 495 L75 155 Z" fill="${navy}" stroke="${gold}" stroke-width="14"/><path d="M400 57 L704 170 L684 492 Q670 631 400 742 Q130 631 116 492 L96 170 Z" fill="none" stroke="white" stroke-width="3"/>`;return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200" viewBox="0 0 800 800" role="img"><title>${escape(title)} — Scholarion Academy badge artwork</title><g font-family="Arial,sans-serif" text-anchor="middle" fill="white">${outline}<circle cx="400" cy="151" r="64" fill="${navy}" stroke="${gold}" stroke-width="6"/><path d="M356 169 Q377 158 400 178 Q423 158 444 169 L444 185 Q423 174 400 194 Q377 174 356 185 Z M400 172 V112 M400 145 L379 125 M400 135 L422 113" fill="none" stroke="white" stroke-width="6"/><g fill="${gold}"><circle cx="400" cy="108" r="7"/><circle cx="377" cy="121" r="7"/><circle cx="425" cy="109" r="7"/></g><text x="400" y="256" font-family="Georgia,serif" font-size="45" font-weight="700">SCHOLARION</text><text x="400" y="294" font-size="27" letter-spacing="7" fill="${gold}">ACADEMY</text><path d="M60 324 H740 L715 355 L740 386 H60 L85 355 Z" fill="${simple?gold:cyan}" stroke="${gold}" stroke-width="3"/><text x="400" y="365" font-size="${type.length>22?23:30}" font-weight="700" fill="${simple?navy:'white'}">${escape(type.toUpperCase())}</text>${text}<text x="400" y="655" font-size="19" fill="${gold}" letter-spacing="3">${micro?'LEARN · BUILD · GROW':'PROGRAM COMPLETION'}</text><text x="400" y="686" font-size="14">${escape(id?'PROGRAM '+id:'SCHOLARION ACADEMY')}</text></g></svg>`;}
const api={svg,lines};if(typeof module!=='undefined')module.exports=api;else root.BadgeTemplate=api;
})(globalThis);
